#include <iostream>
#include <map>
using namespace std;

map<pair<int,int>, long long> all;
map<tuple<int,int,int>, long long> limit;
int n=0, m=0;

long long searchall(int lo, int hi) {
    if (lo == hi) {
        return 1;
    }
    pair<int,int> key = make_pair(lo, hi);
    if (all.count(key)) {
        return all[key];
    }
    all[key] = 0;
    all[key] += searchall(lo + 1, hi);
    all[key] += searchall(lo, hi - 1);
    for (int i = lo + 1; i < hi; ++i) {
        all[key] += searchall(lo, i - 1) * searchall(i + 1, hi);
    }
    return all[key];
}

long long searchlimit(int lo, int hi, int depth) {
    if (lo == hi) {
        if (depth < m) {
            return 1;
        } else {
            return 0;
        }
    }
    tuple<int,int,int> key = make_tuple(lo, hi, depth);
    if (limit.count(key)) {
        return limit[key];
    }
    limit[key] = 0;
    limit[key] += searchlimit(lo + 1, hi, depth + 1);
    limit[key] += searchlimit(lo, hi - 1, depth + 1);
    for (int i = lo + 1; i < hi; ++i) {
        limit[key] += searchlimit(lo, i - 1, depth + 1) * searchlimit(i + 1, hi, depth + 1);
    }
    return limit[key];
}

int main() {
    cin >> n >> m;
    long long ret = searchall(1, n) - searchlimit(1, n, 1);
    cout << ret << endl;
    return 0;
}

